from typing import Any, Literal, Annotated
from pydantic import BaseModel
from fastapi import FastAPI, Body
from fastapi.testclient import TestClient

class Pie(BaseModel):
    time_to_cook: int
    num_ingredients: int

class ApplePie(Pie):
    fruit: Literal["apple"] = "apple"

class PumpkinPie(Pie):
    filling: Literal["pumpkin"] = "pumpkin"

def get_discriminator_value(v: Any) -> str:
    if isinstance(v, dict):
        return v.get("fruit", v.get("filling"))
    return getattr(v, "fruit", getattr(v, "filling", None))

# This is the problematic type
# Note: Tag and Discriminator are likely from pydantic or some other library, 
# but in the problem statement they are used. 
# Wait, Tag and Discriminator are not standard pydantic. 
# Let me check if they are from pydantic. 
# Actually, Pydantic v2 has Discriminator. 
# Let's see if I can import them.
try:
    from pydantic import Discriminator, Tag
except ImportError:
    # If they are not available, I might need to define them or check where they come from.
    # But the problem statement implies they should work.
    # Let's try to use pydantic's Discriminator.
    from pydantic import Discriminator
    class Tag:
        def __init__(self, value):
            self.value = value
        def __repr__(self):
            return f"Tag({self.value})"

Dessert = Annotated[
    Annotated[ApplePie, Tag("apple")] | Annotated[PumpkinPie, Tag("pumpkin")],
    Discriminator(get_discriminator_value),
]

app = FastAPI()

@app.post("/dessert")
async def dinner(dessert: Dessert) -> dict[str, Any]:
    return dessert.model_dump()

client = TestClient(app)

def test_dessert_body():
    # Test ApplePie
    response = client.post("/dessert", json={"time_to_cook": 60, "num_ingredients": 5, "fruit": "apple"})
    assert response.status_code == 200
    assert response.json() == {"time_to_cook": 60, "num_ingredients": 5, "fruit": "apple"}

