    # If they are not in pydantic, maybe they are just placeholders in the problem statement
    # or from another library. But usually in FastAPI/Pydantic context, 
    # they might be related to Pydantic's discriminated unions.
    # Let's try to define them as simple classes if they are just for metadata.
    class Tag:
        def __init__(self, value): self.value = value
    class Discriminator:
        def __init__(self, value): self.value = value

Dessert = Annotated[
    Annotated[ApplePie, Tag("apple")] | Annotated[PumpkinPie, Tag("pumpkin")],
    Discriminator(get_discriminator_value),
]

